#!/usr/bin/env python3
"""Owned fake-pio preservation tests plus compile guards/sdkconfig fixtures."""
import gzip,hashlib,json,os,shutil,subprocess,sys
from pathlib import Path
O=Path(__file__).resolve().parent;F=O/(sys.argv[1] if len(sys.argv)>1 else 'freeze-002');run_id=sys.argv[2] if len(sys.argv)>2 else '001';W=O/('build-config-model-'+run_id);W.mkdir();checks=0;results=[]
def check(v,label):
 global checks
 checks+=1
 if not v:raise AssertionError(label)
def execute(cmd,**kw):
 p=subprocess.run(list(map(str,cmd)),text=True,capture_output=True,**kw);results.append(dict(command=list(map(str,cmd)),returncode=p.returncode,stdout=p.stdout,stderr=p.stderr));return p
env=dict(os.environ,GCOV_PREFIX=str(O/'gcov'),GCOV_PREFIX_STRIP='0',PYTHONDONTWRITEBYTECODE='1')
# Compile flags are checked without any SDK/device or target link.
source=W/'guard.cpp';source.write_text('#include "ecu/flex_hardware.hpp"\nint main(){return ecu::flex::gpio==38?0:1;}\n')
for name,flags,allowed in [('legacy',[],True),('new',['ECU_FLEX_G38_DRAFT=1','ECU_COMPACT_A3=1','ECU_SELECTED_N16R8=1'],True),('missing_all',['ECU_FLEX_G38_DRAFT=1'],False),('missing_selected',['ECU_FLEX_G38_DRAFT=1','ECU_COMPACT_A3=1'],False),('missing_compact',['ECU_FLEX_G38_DRAFT=1','ECU_SELECTED_N16R8=1'],False),('dummy',['ECU_FLEX_G38_DRAFT=1','ECU_COMPACT_A3=1','ECU_SELECTED_N16R8=1','ECU_ENGINE_DUMMY_LOADS=1'],False),('bench',['ECU_FLEX_G38_DRAFT=1','ECU_COMPACT_A3=1','ECU_SELECTED_N16R8=1','ECU_BENCH_PULSES=1'],False)]:
 p=execute(['c++','-std=c++17','-Wall','-Wextra','-Werror','-pedantic','-fsyntax-only','-I'+str(F/'firmware/include'),*['-D'+x for x in flags],source],env=env);check((p.returncode==0)==allowed,'compile guard '+name)
# Execute only a copied SCons pre-script against generated files in owned dirs.
script=F/'scripts/tuning_sdkconfig.py';original=b'CONFIG_ESP_CONSOLE_SECONDARY_USB_SERIAL_JTAG=y\n# CONFIG_ESP_CONSOLE_SECONDARY_NONE is not set\n'
for mode in ('compact_n16r8_web','compact_a3_web','compact_n16r8_flex_dev','compact_a3_timing_bench'):
 root=W/('sdk-'+mode)/'firmware';root.mkdir(parents=True);p=root/('sdkconfig.'+mode);p.write_bytes(original)
 code='import runpy;runpy.run_path('+repr(str(script))+',init_globals={"Import":lambda _:None,"env":{"PIOENV":'+repr(mode)+',"PROJECT_DIR":'+repr(str(root))+'}})'
 r=execute(['python3','-B','-c',code],env=env);check(not r.returncode,'sdk script completed')
 if mode.endswith('timing_bench'):check(p.read_bytes()==original,'unrelated generated config preserved')
 else:
  first=p.read_bytes();check(b'CONFIG_ESP_CONSOLE_SECONDARY_NONE=y' in first and b'\nCONFIG_ESP_CONSOLE_SECONDARY_USB_SERIAL_JTAG=y'not in b'\n'+first,'USB exclusive normalizer')
  backups=list((root.parent/'.cache/engine/tuning-sdkconfigs').glob('*.before'));check(len(backups)==1 and backups[0].read_bytes()==original,'original generated bytes retained')
  r=execute(['python3','-B','-c',code],env=env);check(not r.returncode and p.read_bytes()==first and len(list(backups[0].parent.glob('*.before')))==1,'normalizer idempotent')
root=W/'sdk-symlink/firmware';root.mkdir(parents=True);target=root/'real';target.write_bytes(original);p=root/'sdkconfig.compact_n16r8_flex_dev';p.symlink_to('real')
code='import runpy;runpy.run_path('+repr(str(script))+',init_globals={"Import":lambda _:None,"env":{"PIOENV":"compact_n16r8_flex_dev","PROJECT_DIR":'+repr(str(root))+'}})'
r=execute(['python3','-B','-c',code],env=env);check(r.returncode!=0 and p.is_symlink() and target.read_bytes()==original,'legacy symlink rejected without mutation')
fakebin=W/'fake-bin';fakebin.mkdir();pio=fakebin/'pio';pio.write_text('''#!/usr/bin/env python3
import json,os,sys
from pathlib import Path
r=Path.cwd();out=Path(os.environ['PLATFORMIO_BUILD_DIR']);out.mkdir(parents=True,exist_ok=True)
(out/'pio-command.json').write_text(json.dumps({'argv':sys.argv,'build_dir':str(out)}))
names=[sys.argv[n+1]for n,a in enumerate(sys.argv)if a=='-e']
for name in names:
 p=out/name;p.mkdir();(p/'firmware.elf').write_text('OWNED FAKE BUILD ONLY '+name);(p/'firmware.bin').write_text('OWNED FAKE IMAGE ONLY')
mode=os.environ['REVIEW_FAKE_PIO_MODE']
if mode=='cache_mutation':(r/'firmware/.pio/build/prior/firmware.elf').write_text('owned mutation')
if mode=='source_mutation':(r/'firmware/main/mock.cpp').write_text('owned source mutation')
if mode=='config_mutation':(r/'firmware/sdkconfig.owned_fake').write_text('owned generated config after')
sys.exit(2 if mode=='build_failure'else 0)
''');pio.chmod(0o755)
for mode in ('positive','cache_mutation','source_mutation','build_failure','missing_default','config_mutation'):
 root=W/('wrapper-'+mode);(root/'scripts').mkdir(parents=True);(root/'firmware/main').mkdir(parents=True);(root/'.gitignore').write_text('.cache/\nfirmware/.pio/\nfirmware/sdkconfig.*\n');(root/'firmware/platformio.ini').write_text('[env:owned_fake]\n');(root/'firmware/main/mock.cpp').write_text('original owned source');wrapper=root/'scripts/build_firmware_preserved.py';shutil.copyfile(F/'scripts/build_firmware_preserved.py',wrapper)
 (root/'web').mkdir();(root/'web/index.html').write_text('OWNED UI FIXTURE\n')
 (root/'firmware/main/web_assets.hpp').write_text('OWNED PRIOR GENERATED HEADER\n')
 (root/'scripts/embed_web.py').write_text('from pathlib import Path\nr=Path(__file__).resolve().parents[1]\nh=(r/"web/index.html").read_text()\n(r/"firmware/main/web_assets.hpp").write_text(\'inline constexpr char index[]=R"ECU_ASSET(\'+h+\')ECU_ASSET";\')\n')
 generated=root/'firmware/sdkconfig.owned_fake';generated.write_text('owned generated config before')
 check(execute(['git','init','-q',root],env=env).returncode==0,'owned git init')
 default=root/'firmware/.pio/build/prior/firmware.elf'
 if mode!='missing_default':default.parent.mkdir(parents=True);default.write_text('original owned cache');(default.parent/'same.elf').symlink_to('firmware.elf')
 e=dict(env,PATH=str(fakebin)+os.pathsep+env['PATH'],REVIEW_FAKE_PIO_MODE=mode,PLATFORMIO_BUILD_DIR='/unused-inherited-path')
 output=root/'.cache/run';command=['python3','-B',wrapper,'--output',output,'--environment','owned_fake'];p=execute(command,cwd=root,env=e);summary=json.loads((output/'summary.json').read_text());good=mode in ('positive','missing_default','config_mutation');check((p.returncode==0)==good,'wrapper result '+mode)
 check(summary['build_dir_override']==str(output/'build') and summary['flashed']is False,'fresh owned build dir/compile-only receipt')
 check(summary['default_cache_unchanged']==(mode!='cache_mutation') and summary['source_inputs_unchanged']==(mode!='source_mutation'),'mutations independently detected')
 if 'elf_archives' in summary:
  check(len(summary['elf_archives'])==1,'ELF archive count')
  a=summary['elf_archives'][0];p=output/a['path'];body=gzip.decompress(p.read_bytes());elf=output/'build/owned_fake/firmware.elf'
  check(body==elf.read_bytes() and hashlib.sha256(p.read_bytes()).hexdigest()==a['sha256'] and hashlib.sha256(body).hexdigest()==a['elf_sha256'],'lossless archived ELF receipt')
 if 'generated_sdkconfigs' in summary:
  check(len(summary['generated_sdkconfigs'])==1,'SDK config record count');row=summary['generated_sdkconfigs'][0]
  check(row['original_present'] and (output/row['retained']).read_text()=='owned generated config before','SDK config original retained')
  check((output/row['after_copy']).read_bytes()==generated.read_bytes() and row['after_sha256']==hashlib.sha256(generated.read_bytes()).hexdigest(),'SDK config after copied independently')
 if mode!='missing_default':check((output/'retained-default-cache/prior/firmware.elf').read_text()=='original owned cache','retained original cache remains reviewable')
 if mode=='positive':
  check(default.read_text()=='original owned cache' and (output/'retained-default-cache/prior/same.elf').is_symlink(),'default bytes and retained symlink preserved')
  r=execute(command,cwd=root,env=e);check(r.returncode!=0,'existing output rejected')
  r=execute(['python3','-B',wrapper,'--output',root/'not-cache','--environment','owned_fake'],cwd=root,env=e);check(r.returncode!=0 and not(root/'not-cache').exists(),'output confined to own cache')
  r=execute(['python3','-B',wrapper,'--output',root/'.cache/bad-env','--environment','owned_fake;upload'],cwd=root,env=e);check(r.returncode!=0 and not(root/'.cache/bad-env').exists(),'non-environment input rejected before action')
  if 'generated_sdkconfigs' in summary:
   generated.rename(generated.with_name('real-sdkconfig'));generated.symlink_to('real-sdkconfig')
   r=execute(['python3','-B',wrapper,'--output',root/'.cache/symlink-config','--environment','owned_fake'],cwd=root,env=e)
   check(r.returncode!=0 and generated.is_symlink() and generated.read_text()=='owned generated config before' and not(root/'.cache/symlink-config/build').exists(),'historical SDK symlink rejected before fake PIO')
report={'passed':True,'checks':checks,'commands':results,'scope':'Native syntax and owned generated-config/fake-pio models only. No actual PlatformIO build or device command run by this probe.','environment':{k:env[k]for k in ('GCOV_PREFIX','GCOV_PREFIX_STRIP','PYTHONDONTWRITEBYTECODE')}}
(O/('build-config-probe-'+run_id+'.json')).write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'passed':True,'checks':checks}))
